@Composable
internal fun UiIconButton(
    icon: UiIcon,
    label: String,
    color: Color,
    action: () -> Unit,
    enabled: Boolean = true,
    fill: Color = Color.Transparent,
) {
    Box(
        Modifier.size(AndroidControlSize.target).clip(CircleShape).background(fill)
            .clickable(enabled = enabled, role = Role.Button, onClick = action)
            .semantics { contentDescription = label },
        contentAlignment = Alignment.Center,
    ) {
        UiGlyph(icon, color)
    }
}

@Composable
internal fun UiGlyph(icon: UiIcon, color: Color, iconSize: Dp = AndroidControlSize.icon) {
    val path = remember(icon) { PathParser().parsePathString(icon.pathData).toPath() }
    Canvas(Modifier.size(iconSize)) {
        scale(size.width / 24f, size.height / 24f, pivot = Offset.Zero) {
            drawPath(path, color)
        }
    }
}
